def main() -> int:
    c.setup_console()
    c.write_csv(ROOT / "sources.csv", c.SOURCE_COLUMNS, [
        dict(zip(c.SOURCE_COLUMNS, row)) for row in SOURCES
    ])
    c.write_csv(ROOT / "03-evidence-ledger.csv", c.LEDGER_COLUMNS, [
        dict(zip(c.LEDGER_COLUMNS, row)) for row in LEDGER
    ])
    print(f"источников: {len(SOURCES)}, записей: {len(LEDGER)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
